tryImport('departments.json', () => {
  const data = readJsonFile(path.join(ORG_DIR, 'departments.json'));
  if (!data) return;
  if (data.departments) {
    const s = db.prepare('INSERT OR REPLACE INTO departments (id,label,description,head,color,icon,sort_order,active) VALUES (?,?,?,?,?,?,?,?)');
    db.transaction(() => {
      for (const d of Object.values(data.departments)) s.run(d.id, d.label, d.description, d.head, d.color, d.icon, d.order || 0, d.active !== false ? 1 : 0);
    })();
  }
  if (data.phases) {
    const s = db.prepare('INSERT OR REPLACE INTO phases (id,label,description,color,sort_order) VALUES (?,?,?,?,?)');
    db.transaction(() => {
      for (const p of Object.values(data.phases)) s.run(p.id, p.label, p.description, p.color, p.order || 0);
    })();
  }
});

